INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 1, '목적', '제1장 총칙', '제1조(목적) 이 규정은 예원예술대학교 정관, 학칙, 직제규정에 의거 설치된 각 부서의 소관 사무를 규정 함을 목적으로 한다.<개정 2016.8.22.>

', '[{"type":"text","num":"","text":"제1조(목적) 이 규정은 예원예술대학교 정관, 학칙, 직제규정에 의거 설치된 각 부서의 소관 사무를 규정 함을 목적으로 한다.<개정 2016.8.22.>"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 2, '업무처리', '제1장 총칙', '제2조(업무처리) 동일한 사무가 둘 이상의 부서에 관련되는 업무는 그 비중이 많은 부서에서 처리함을 원칙으로 하며, 처리할 부서를 결정할 수 없는 경우에는 관련 부서의 협의를 거쳐 규정관리 부서장의 유권해석에 따른다.<개정 2016.8.22.>

', '[{"type":"text","num":"","text":"제2조(업무처리) 동일한 사무가 둘 이상의 부서에 관련되는 업무는 그 비중이 많은 부서에서 처리함을 원칙으로 하며, 처리할 부서를 결정할 수 없는 경우에는 관련 부서의 협의를 거쳐 규정관리 부서장의 유권해석에 따른다.<개정 2016.8.22.>"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 3, '각 부서의 공통업무', '제1장 총칙', '제3조(각 부서의 공통업무)
① 각 부서의 정책결정이 필요한 업무는 기획조정처의 사전 심의 절차를 거쳐야 한다.<개정 2014.12.1><개정 2016.8.22><개정 2017.2.20><개정 2017.09.25>
② 각 부서는 다음 각 호의 업무를 공통으로 수행한다.<개정 2016.8.22.>
1. 부서별 업무계획 및 발전계획 수립
2. 부서별 업무분석 및 제도개선
3. 부서별 업무와 관련한 대학경쟁력 제고 방안 수립 및 실천
4. 소관업무의 기본운영계획 수립 및 시행에 관한 사무
5. 소관업무에 관한 예산편성 요구
6. 소관업무에 관련 수입 및 지출 원인행위
7. 소관업무에 관한 제규정의 제정 및 개․폐에 대한 입안
8. 소속 교직원의 근무지 지정 및 사무분장
9. 소속 교직원 복무관리(근무태도, 국내외 출장 신청, 휴가, 외출 등)
10. 소관업무 관련사항의 보고
11. 부서별 업무와 관련한 자료 및 통계자료의 작성, 유지, 관리
12. 부서별 업무와 관련 위원회의 구성과 운영에 관한 사항
13. 부서가 사용하거나 관장하는 건물, 시설물, 비품 및 소모품 등의 유지관리
14. 자체관리 시설물의 보안, 방화, 환경미화 업무
15. 사무관리에 관한 사항
16. 타부서에서 요구하는 업무의 지원
17. 그 밖에 소관업무와 관련되거나 부수되는 업무

', '[{"type":"text","num":"","text":"제3조(각 부서의 공통업무)"},{"type":"text","num":"①","text":"각 부서의 정책결정이 필요한 업무는 기획조정처의 사전 심의 절차를 거쳐야 한다.<개정 2014.12.1><개정 2016.8.22><개정 2017.2.20><개정 2017.09.25>"},{"type":"text","num":"②","text":"각 부서는 다음 각 호의 업무를 공통으로 수행한다.<개정 2016.8.22.>"},{"type":"text","num":"1.","text":"부서별 업무계획 및 발전계획 수립"},{"type":"text","num":"2.","text":"부서별 업무분석 및 제도개선"},{"type":"text","num":"3.","text":"부서별 업무와 관련한 대학경쟁력 제고 방안 수립 및 실천"},{"type":"text","num":"4.","text":"소관업무의 기본운영계획 수립 및 시행에 관한 사무"},{"type":"text","num":"5.","text":"소관업무에 관한 예산편성 요구"},{"type":"text","num":"6.","text":"소관업무에 관련 수입 및 지출 원인행위"},{"type":"text","num":"7.","text":"소관업무에 관한 제규정의 제정 및 개․폐에 대한 입안"},{"type":"text","num":"8.","text":"소속 교직원의 근무지 지정 및 사무분장"},{"type":"text","num":"9.","text":"소속 교직원 복무관리(근무태도, 국내외 출장 신청, 휴가, 외출 등)"},{"type":"text","num":"10.","text":"소관업무 관련사항의 보고"},{"type":"text","num":"11.","text":"부서별 업무와 관련한 자료 및 통계자료의 작성, 유지, 관리"},{"type":"text","num":"12.","text":"부서별 업무와 관련 위원회의 구성과 운영에 관한 사항"},{"type":"text","num":"13.","text":"부서가 사용하거나 관장하는 건물, 시설물, 비품 및 소모품 등의 유지관리"},{"type":"text","num":"14.","text":"자체관리 시설물의 보안, 방화, 환경미화 업무"},{"type":"text","num":"15.","text":"사무관리에 관한 사항"},{"type":"text","num":"16.","text":"타부서에서 요구하는 업무의 지원"},{"type":"text","num":"17.","text":"그 밖에 소관업무와 관련되거나 부수되는 업무"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 4, '비서실', '제2장 총장 및 부총장 직속', '제4조(비서실)
① 비서실은 다음 각 호의 사항을 분장한다.<개정 2019.12.30.><개정 2023.11.07><개정 2025.12.09>
1. 총장 보좌
2. 총장 지시사항 처리 및 업무연락
3. 총장의 일정 관리 및 수행
4. 교내·외 행사진행 보고
5. 처장회 운영
6. 내빈안내 및 의전
7. 총장실, 부총장실 관리
8. 교기·교가 및 응원가 관리에 관한 업무
9. 소관 제위원회 운영관리에 관한 업무
10. 공문서 접수 및 발송에 관한 업무<신설 2025.12.09>
11. 그 밖에 위 각 호에 부수되는 업무 및 타부서의 업무에 속하지 아니하는 총장 및 부총장의 보좌에 관한 사항<개정 2025.12.09.>

', '[{"type":"text","num":"","text":"제4조(비서실)"},{"type":"text","num":"①","text":"비서실은 다음 각 호의 사항을 분장한다.<개정 2019.12.30.><개정 2023.11.07><개정 2025.12.09>"},{"type":"text","num":"1.","text":"총장 보좌"},{"type":"text","num":"2.","text":"총장 지시사항 처리 및 업무연락"},{"type":"text","num":"3.","text":"총장의 일정 관리 및 수행"},{"type":"text","num":"4.","text":"교내·외 행사진행 보고"},{"type":"text","num":"5.","text":"처장회 운영"},{"type":"text","num":"6.","text":"내빈안내 및 의전"},{"type":"text","num":"7.","text":"총장실, 부총장실 관리"},{"type":"text","num":"8.","text":"교기·교가 및 응원가 관리에 관한 업무"},{"type":"text","num":"9.","text":"소관 제위원회 운영관리에 관한 업무"},{"type":"text","num":"10.","text":"공문서 접수 및 발송에 관한 업무<신설 2025.12.09>"},{"type":"text","num":"11.","text":"그 밖에 위 각 호에 부수되는 업무 및 타부서의 업무에 속하지 아니하는 총장 및 부총장의 보좌에 관한 사항<개정 2025.12.09.>"}]');
