INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 8, '사회봉사센터', '제3장 교학지원처', '제8조(사회봉사센터) 교학지원처에 사회봉사센터를 두고 다음 각 호의 업무를 담당한다.<조신설 2015.1.13.>
1. 센터 사업계획 수립
2. 사회봉사 및 사회복지 서비스 프로그램 개발
3. 국내 및 해외 사회봉사활동 기관과의 상호교류 및 네트워크 구축
4. 사회봉사활동자의 교육，배치，평가
5. 사회봉사활동 지원 및 관리
6. 사회봉사활동 및 사회복지사업 실천
7. 사회봉사교과목 개설 및 학점관리
8. 사회봉사 및 사회복지분야에 대한 조사 연구
9. 그 밖에 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제8조(사회봉사센터) 교학지원처에 사회봉사센터를 두고 다음 각 호의 업무를 담당한다.<조신설 2015.1.13.>"},{"type":"text","num":"1.","text":"센터 사업계획 수립"},{"type":"text","num":"2.","text":"사회봉사 및 사회복지 서비스 프로그램 개발"},{"type":"text","num":"3.","text":"국내 및 해외 사회봉사활동 기관과의 상호교류 및 네트워크 구축"},{"type":"text","num":"4.","text":"사회봉사활동자의 교육，배치，평가"},{"type":"text","num":"5.","text":"사회봉사활동 지원 및 관리"},{"type":"text","num":"6.","text":"사회봉사활동 및 사회복지사업 실천"},{"type":"text","num":"7.","text":"사회봉사교과목 개설 및 학점관리"},{"type":"text","num":"8.","text":"사회봉사 및 사회복지분야에 대한 조사 연구"},{"type":"text","num":"9.","text":"그 밖에 위 각 호에 부수되는 사항"}]');
