INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 10, '제10조의5(학생종합서비스센터)', '제3장 교학지원처', '제10조의5(학생종합서비스센터) 교학지원처에 학생종합서비스센터를 두고 다음 각 호의 업무를 담당한
다. <조신설 2023.11.07>
1. 학생행사 지도
2. 학생간행물 및 광고물 지도
3. 학생학술활동 지도
4. 학생 자치기구 선거지도에 관한 업무
5. 학생회 집회 조정 및 지도에 관한 업무
6. 학생 생활 지도에 관한 업무
7. 학생회 지원 관리에 관한 업무
8. 학생 문화ㆍ예술 활동에 관한 업무
9. 학생복지시설관리에 관한 업무
10. 교내 복지ㆍ후생 업소 관리 및 운영에 관한 업무
11. 기타 위 각호에 부수되는 사항

', '[{"type":"text","num":"","text":"제10조의5(학생종합서비스센터) 교학지원처에 학생종합서비스센터를 두고 다음 각 호의 업무를 담당한"},{"type":"text","num":"다.","text":"<조신설 2023.11.07>"},{"type":"text","num":"1.","text":"학생행사 지도"},{"type":"text","num":"2.","text":"학생간행물 및 광고물 지도"},{"type":"text","num":"3.","text":"학생학술활동 지도"},{"type":"text","num":"4.","text":"학생 자치기구 선거지도에 관한 업무"},{"type":"text","num":"5.","text":"학생회 집회 조정 및 지도에 관한 업무"},{"type":"text","num":"6.","text":"학생 생활 지도에 관한 업무"},{"type":"text","num":"7.","text":"학생회 지원 관리에 관한 업무"},{"type":"text","num":"8.","text":"학생 문화ㆍ예술 활동에 관한 업무"},{"type":"text","num":"9.","text":"학생복지시설관리에 관한 업무"},{"type":"text","num":"10.","text":"교내 복지ㆍ후생 업소 관리 및 운영에 관한 업무"},{"type":"text","num":"11.","text":"기타 위 각호에 부수되는 사항"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 10, '제10조의6(전북희망캠퍼스 교육지원센터)', '제3장 교학지원처', '제10조의6(전북희망캠퍼스 교육지원센터) 교학지원처에 전북희망캠퍼스 교육지원센터를 두고 다음 각 호의 업무를 담당한다.<신설 2025.09.24>
