:"text","num":"33.","text":"사업 관련 경영분석 평가"},{"type":"text","num":"34.","text":"소관 제위원회 운영관리에 관한 업무"},{"type":"text","num":"35.","text":"그 밖에 위 각 호에 부수되는 사항"},{"type":"text","num":"②","text":"성과관리 업무"},{"type":"text","num":"1.","text":"장단기발전계획 및 경영전략 수립"},{"type":"text","num":"2.","text":"대학 전반의 주요정책과 운영계획 수립"},{"type":"text","num":"3.","text":"대학특성화 정책수립 및 지원"},{"type":"text","num":"4.","text":"정책사업 개발 및 정책연구 지원 업무"},{"type":"text","num":"5.","text":"대내외 평가 기본계획 수립 및 시행"},{"type":"text","num":"6.","text":"통계자료 수집과 분석 및 관리"},{"type":"text","num":"7.","text":"대학정보공시에 관한 업무"},{"type":"text","num":"8.","text":"대학특성화 자료 입력 및 공시 업무"},{"type":"text","num":"9.","text":"대학평가 및 대학기관인증평가 업무"},{"type":"text","num":"10.","text":"대학 평가와 관련한 분석, 관리 업무"},{"type":"text","num":"11.","text":"자체평가 실시 및 관련 개선사항 점검 업무"},{"type":"text","num":"12.","text":"대학 주요 지표 데이터 분석 및 연구 업무"},{"type":"text","num":"13.","text":"성과관리시스템 구축 및 운영 업무"},{"type":"text","num":"14.","text":"그 밖에 위 각 호에 부수되는 사항"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 12, '행정지원처', '제5장 행정지원처', '제12조(행정지원처) 행정지원처에 행정지원팀을 두고 다음 사항을 분장한다.<개정 2016.8.22.><개정 2017.2.20.><개정 2020.08.05.><개정 2021.01.21.><개정 2023.11.07.><개정 2025.09.24.><개정 2025.12.09>
① 행정지원 업무(총무)
1. 총장 및 행정지원처장 직인관리에 관한 업무
2. <삭제 2025.12.09>
3. 직인 등록, 변경 및 폐기에 관한 업무
4. 비밀문서 관리 및 보존에 관한 업무
5. 비밀취급인가 취득 및 해지에 관한 업무
6. 보안 및 비상계획에 관한 업무
7. 직원 복무관리에 관한 업무
8. 당직관리에 관한 업무
9. 문서 보존, 수발, 이전에 관한 업무
10. 우편물 관리에 관한 업무
11. 교내 행사 준비 및 진행에 관한 업무
12. 민원사무에 관한 업무
13. 사무 인수ㆍ인계에 관한 업무
14. 정보공개에 관한 업무
15. 직원 출장 및 파견에 관한 업무
16. 일반직원 인사명령(승진, 신규임용 등)에 관한 업무
17. 일반직원 임용 및 인사기록에 관한 업무
18. 일반직원 상훈, 징계, 전력 및 신원조회에 관한 업무
19. 일반직원 교육훈련 및 국외 여행 파견에 관한 업무
20. 일반직원 제증명 발급에 관한 업무
21. 교직원 사대보험 관련 업무
22. 직원 인사위원회 사무에 관한 업무
23. 교직원 후생 복지에 관한 업무
24. 부동산 취득, 처분, 자산보험 및 사후관리(재산관리)에 관한 업무
25. 고정자산의 관리, 전용, 폐기 및 기타 처분에 관한 업무
26. 시설물의 공사, 유지, 보수도급 계약에 관한 업무
27. 각종 시설물의 등기(건축, 토목, 기타 공사 사항)에 관한 업무
28. 실험실습기자재 구입, 발주 및 검수에 관한 업무
29. 제반 구입 물품의 검수부등기, 수불에 관한 업무
30. 교내・외 전화 운용에 관한 업무
31. 비품, 실험실습기자재 교구의 유지, 보수, 관리, 운용에 관한 업무
32. 총괄 자산의 재평가 및 보고에 관한 업무
33. 공사 및 각종 인허가에 관련된 업무
34. 각종 시설 공사 감독 및 준공 하자 검사에 관한 업무
35. 조경시설의 유지, 보수 및 운용 관리에 관한 업무
36. 각 건물 유지, 보수 및 운용 관리에 관한 업무
37. 시설활용 조사 관리에 관한 업무
38. 설비시설(전기, 통신, 소방, 냉・난방 등) 운용 관리에 관한 업무
39. 영선업무
40. 하수도 시설 유지, 보수, 운용 관리에 관한 업무
41. 변전실, 기계실, 영수실, 보일러실 운용 관리에 관한 업무
42. 환경(폐수 처리 및 정화조 등)에 관한 업무
43. 환경미화에 관한 업무
44. 학교 환경위생 정화구역 관리에 관한 업무
45. 교내 경비에 관한 업무
46. 스쿨버스 계약에 관한 업무
47. 장비 사용 및 대여에 관한 업무
48. 교내 시설물(강당, 체육관 등) 사용허가에 관한 업무
49. 교내 시설 및 부착물의 발주에 관한 업무
50. 학교소유의 차량운행 및 관리에 관한 업무
51. 구내 시설물의 임대 및 기타 계약체결에 관한 업무
52. 물품 구매 입찰에 관한 업무
53. 소모품 수불 및 관리에 관한 업무
54. 검수조서 및 대장의 관리
55. 검수실적 통계
56. 소관 제위원회 운영관리에 관한 업무
57. 기타 각 위 각 호에 부수되는 사항
② 행정지원 업무(재무)
1. 세입ㆍ세출 예산 집행에 관한 업무
2. 기성회 회계 및 자금관리에 관한 업무
3. 교직원 급여 및 제수당 산출에 관한 업무
4. 보수 지급 및 원천징수에 관한 업무
5. 교직원 사학연금 및 공제회 운영에 관한 업무
6. 내국인 등록금 수납 및 환급에 관한 업무<개정 2025.09.24>
7. 차입금에 대한 원리금 상환업무
8. 공공요금 지불 원인 행위에 관한 업무
9. 제세공과금 납부에 관한 업무(부속기관 공과금 포함)
10. 연말 정산의 업무
11. 결산 업무
12. 출판기금 관리에 관한 업무
13. 발전기금 조성 및 운영 업무
14. 교내ㆍ외 연구비 원천징수에 관한 업무
15. 연구기금 관리에 관한 업무
16. 기타 재무에 관한 사항
17. 소관 제위원회 운영관리에 관한 업무
18. 기타 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제12조(행정지원처) 행정지원처에 행정지원팀을 두고 다음 사항을 분장한다.<개정 2016.8.22.><개정 2017.2.20.><개정 2020.08.05.><개정 2021.01.21.><개정 2023.11.07.><개정 2025.09.24.><개정 2025.12.09>"},{"type":"text","num":"①","text":"행정지원 업무(총무)"},{"type":"text","num":"1.","text":"총장 및 행정지원처장 직인관리에 관한 업무"},{"type":"text","num":"2.","text":"<삭제 2025.12.09>"},{"type":"text","num":"3.","text":"직인 등록, 변경 및 폐기에 관한 업무"},{"type":"text","num":"4.","text":"비밀문서 관리 및 보존에 관한 업무"},{"type":"text","num":"5.","text":"비밀취급인가 취득 및 해지에 관한 업무"},{"type":"text","num":"6.","text":"보안 및 비상계획에 관한 업무"},{"type":"text","num":"7.","text":"직원 복무관리에 관한 업무"},{"type":"text","num":"8.","text":"당직관리에 관한 업무"},{"type":"text","num":"9.","text":"문서 보존, 수발, 이전에 관한 업무"},{"type":"text","num":"10.","text":"우편물 관리에 관한 업무"},{"type":"text","num":"11.","text":"교내 행사 준비 및 진행에 관한 업무"},{"type":"text","num":"12.","text":"민원사무에 관한 업무"},{"type":"text","num":"13.","text":"사무 인수ㆍ인계에 관한 업무"},{"type":"text","num":"14.","text":"정보공개에 관한 업무"},{"type":"text","num":"15.","text":"직원 출장 및 파견에 관한 업무"},{"type":"text","num":"16.","text":"일반직원 인사명령(승진, 신규임용 등)에 관한 업무"},{"type":"text","num":"17.","text":"일반직원 임용 및 인사기록에 관한 업무"},{"type":"text","num":"18.","text":"일반직원 상훈, 징계, 전력 및 신원조회에 관한 업무"},{"type":"text","num":"19.","text":"일반직원 교육훈련 및 국외 여행 파견에 관한 업무"},{"type":"text","num":"20.","text":"일반직원 제증명 발급에 관한 업무"},{"type":"text","num":"21.","text":"교직원 사대보험 관련 업무"},{"type":"text","num":"22.","text":"직원 인사위원회 사무에 관한 업무"},{"type":"text","num":"23.","text":"교직원 후생 복지에 관한 업무"},{"type":"text","num":"24.","text":"부동산 취득, 처분, 자산보험 및 사후관리(재산관리)에 관한 업무"},{"type":"text","num":"25.","text":"고정자산의 관리, 전용, 폐기 및 기타 처분에 관한 업무"},{"type":"text","num":"26.","text":"시설물의 공사, 유지, 보수도급 계약에 관한 업무"},{"type":"text","num":"27.","text":"각종 시설물의 등기(건축, 토목, 기타 공사 사항)에 관한 업무"},{"type":"text","num":"28.","text":"실험실습기자재 구입, 발주 및 검수에 관한 업무"},{"type":"text","num":"29.","text":"제반 구입 물품의 검수부등기, 수불에 관한 업무"},{"type":"text","num":"30.","text":"교내・외 전화 운용에 관한 업무"},{"type":"text","num":"31.","text":"비품, 실험실습기자재 교구의 유지, 보수, 관리, 운용에 관한 업무"},{"type":"text","num":"32.","text":"총괄 자산의 재평가 및 보고에 관한 업무"},{"type":"text","num":"33.","text":"공사 및 각종 인허가에 관련된 업무"},{"type":"text","num":"34.","text":"각종 시설 공사 감독 및 준공 하자 검사에 관한 업무"},{"type":"text","num":"35.","text":"조경시설의 유지, 보수 및 운용 관리에 관한 업무"},{"type":"text","num":"36.","text":"각 건물 유지, 보수 및 운용 관리에 관한 업무"},{"type":"text","num":"37.","text":"시설활용 조사 관리에 관한 업무"},{"type":"text","num":"38.","text":"설비시설(전기, 통신, 소방, 냉・난방 등) 운용 관리에 관한 업무"},{"type":"text","num":"39.","text":"영선업무"},{"type":"text","num":"40.","text":"하수도 시설 유지, 보수, 운용 관리에 관한 업무"},{"type":"text","num":"41.","text":"변전실, 기계실, 영수실, 보일러실 운용 관리에 관한 업무"},{"type":"text","num":"42.","text":"환경(폐수 처리 및 정화조 등)에 관한 업무"},{"type":"text","num":"43.","text":"환경미화에 관한 업무"},{"type":"text","num":"44.","text":"학교 환경위생 정화구역 관리에 관한 업무"},{"type":"text","num":"45.","text":"교내 경비에 관한 업무"},{"type":"text","num":"46.","text":"스쿨버스 계약에 관한 업무"},{"type":"text","num":"47.","text":"장비 사용 및 대여에 관한 업무"},{"type":"text","num":"48.","text":"교내 시설물(강당, 체육관 등) 사용허가에 관한 업무"},{"type":"text","num":"49.","text":"교내 시설 및 부착물의 발주에 관한 업무"},{"type":"text","num":"50.","text":"학교소유의 차량운행 및 관리에 관한 업무"},{"type":"text","num":"51.","text":"구내 시설물의 임대 및 기타 계약체결에 관한 업무"},{"type":"text","num":"52.","text":"물품 구매 입찰에 관한 업무"},{"type":"text","num":"53.","text":"소모품 수불 및 관리에 관한 업무"},{"type":"text","num":"54.","text":"검수조서 및 대장의 관리"},{"type":"text","num":"55.","text":"검수실적 통계"},{"type":"text","num":"56.","text":"소관 제위원회 운영관리에 관한 업무"},{"type":"text","num":"57.","text":"기타 각 위 각 호에 부수되는 사항"},{"type":"text","num":"②","text":"행정지원 업무(재무)"},{"type":"text","num":"1.","text":"세입ㆍ세출 예산 집행에 관한 업무"},{"type":"text","num":"2.","text":"기성회 회계 및 자금관리에 관한 업무"},{"type":"text","num":"3.","text":"교직원 급여 및 제수당 산출에 관한 업무"},{"type":"text","num":"4.","text":"보수 지급 및 원천징수에 관한 업무"},{"type":"text","num":"5.","text":"교직원 사학연금 및 공제회 운영에 관한 업무"},{"type":"text","num":"6.","text":"내국인 등록금 수납 및 환급에 관한 업무<개정 2025.09.24>"},{"type":"text","num":"7.","text":"차입금에 대한 원리금 상환업무"},{"type":"text","num":"8.","text":"공공요금 지불 원인 행위에 관한 업무"},{"type":"text","num":"9.","text":"제세공과금 납부에 관한 업무(부속기관 공과금 포함)"},{"type":"text","num":"10.","text":"연말 정산의 업무"},{"type":"text","num":"11.","text":"결산 업무"},{"type":"text","num":"12.","text":"출판기금 관리에 관한 업무"},{"type":"text","num":"13.","text":"발전기금 조성 및 운영 업무"},{"type":"text","num":"14.","text":"교내ㆍ외 연구비 원천징수에 관한 업무"},{"type":"text","num":"15.","text":"연구기금 관리에 관한 업무"},{"type":"text","num":"16.","text":"기타 재무에 관한 사항"},{"type":"text","num":"17.","text":"소관 제위원회 운영관리에 관한 업무"},{"type":"text","num":"18.","text":"기타 위 각 호에 부수되는 사항"}]');
