', '[{"type":"text","num":"","text":"제13조(행정지원실) 삭제 <2017.09.25>"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 14, '산학협력팀', '제6장 산학협력단', '제14조(산학협력팀) 산학협력단에 산학협력팀을 두고 다음 사항을 분장한다.
1. 산학협력단장 직인 관리 업무
2. 산학협력 계획수립에 관한 업무
3. 산학협력협약서 체결 및 관리에 관한 업무
4. 산학협력협약서 체결기관 관리에 관한 업무
5. 국내외 대학 및 연구기관 자매결연에 관한 업무
6. 지적재산권 관리에 관한 업무
7. 산학협력단운영 관련 회계(예산 및 결산)에 관한 업무
8. 관학협력에 관한 사항
9. 협력연구소 지원에 관한 사항
10. 학교기업 설립 및 운영에 관한 사항
11. 부설연구소 개폐 및 지원에 관한 사항
12. 외부 연구용역 계약․관리에 관한 업무
13. 외부 용역사업추진 및 시행에 관한 업무
14. 기타 산학 및 대외협력에 관한 사항
15. 소관 제위원회 운영관리에 관한 업무
16. 기타 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제14조(산학협력팀) 산학협력단에 산학협력팀을 두고 다음 사항을 분장한다."},{"type":"text","num":"1.","text":"산학협력단장 직인 관리 업무"},{"type":"text","num":"2.","text":"산학협력 계획수립에 관한 업무"},{"type":"text","num":"3.","text":"산학협력협약서 체결 및 관리에 관한 업무"},{"type":"text","num":"4.","text":"산학협력협약서 체결기관 관리에 관한 업무"},{"type":"text","num":"5.","text":"국내외 대학 및 연구기관 자매결연에 관한 업무"},{"type":"text","num":"6.","text":"지적재산권 관리에 관한 업무"},{"type":"text","num":"7.","text":"산학협력단운영 관련 회계(예산 및 결산)에 관한 업무"},{"type":"text","num":"8.","text":"관학협력에 관한 사항"},{"type":"text","num":"9.","text":"협력연구소 지원에 관한 사항"},{"type":"text","num":"10.","text":"학교기업 설립 및 운영에 관한 사항"},{"type":"text","num":"11.","text":"부설연구소 개폐 및 지원에 관한 사항"},{"type":"text","num":"12.","text":"외부 연구용역 계약․관리에 관한 업무"},{"type":"text","num":"13.","text":"외부 용역사업추진 및 시행에 관한 업무"},{"type":"text","num":"14.","text":"기타 산학 및 대외협력에 관한 사항"},{"type":"text","num":"15.","text":"소관 제위원회 운영관리에 관한 업무"},{"type":"text","num":"16.","text":"기타 위 각 호에 부수되는 사항"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 14, '제14조의2(지역혁신센터)', '제6장 산학협력단', '제14조의2(지역혁신센터) 산학협력단에 지역혁신센터를 두고 다음 각 호의 업무를 담당한다. <신설 2023.10.05.>
1. 지역혁신센터 종합계획 수립 및 운영
2. 지자체 및 관련기관 협력체제 구축
3. 지역혁신을 위한 네트워크 구축 및 지원사업 활성화
4. 지역콘텐츠 개발 및 인프라 구축
5. 지역 맞춤형 사업 발굴 지원
6. 그 밖에 각 호에 부수되는 사업

', '[{"type":"text","num":"","text":"제14조의2(지역혁신센터) 산학협력단에 지역혁신센터를 두고 다음 각 호의 업무를 담당한다. <신설 2023.10.05.>"},{"type":"text","num":"1.","text":"지역혁신센터 종합계획 수립 및 운영"},{"type":"text","num":"2.","text":"지자체 및 관련기관 협력체제 구축"},{"type":"text","num":"3.","text":"지역혁신을 위한 네트워크 구축 및 지원사업 활성화"},{"type":"text","num":"4.","text":"지역콘텐츠 개발 및 인프라 구축"},{"type":"text","num":"5.","text":"지역 맞춤형 사업 발굴 지원"},{"type":"text","num":"6.","text":"그 밖에 각 호에 부수되는 사업"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 15, '정보도서관', '제7장 부속 및 부설기관', '제15조(정보도서관) 정보도서관은 다음의 업무를 관장한다.<개정 2016.8.22><개정 2017.2.20.><개정 2021.8.27.>
1. 국내․외 기관 및 도서관과의 자료교환 업무
2. 도서 구입의뢰, 등록, 분류 및 편목에 관한 업무
3. 신착 도서 목록 발간 업무
4. 타 기관과 공동 데이터 구축 업무
5. 타 대학 도서관 열람의뢰서 및 열람증 발급 업무
6. 도서원부 관리 업무
7. 도서관 이용교육 및 안내물 제작․홍보 업무
8. 자료(공통 선정)선정, 취합 및 발주 업무
9. 자유열람실 운영관리에 관한 업무
10. 도서관 건물 및 시설물 관리 업무(방역 포함)
11. 원문 데이터베이스 구축 업무
12. 도서대출 및 반납 업무
13. 분실도서 변상 및 연체료 징수에 관한 업무
14. 파본도서 수리 및 도서제본에 관한 업무
15. 망실, 제적도서에 관한 업무
16. 교사자료수집, 보관, 관리업무
17. 장서의 보존 관리 및 점검 업무
18. 각종 정보자료의 참고문헌 봉사업무
19. 각종 간행도서의 보관, 관리 업무
20. 자료복사 서비스에 관한 업무
21. 학술문헌정보 국내외 기관과 상호대차 업무
22. 야간 열람봉사에 관한 업무
23. 학내 정보화 계획 및 추진
24. 교육 및 연구에 관한 정보처리 지원
25. 학사행정, 일반행정, 연구행정에 관한 정보시스템 개발 및 유지 관리
26. 전산망 관리 및 운영
27. 대학, 부속기관의 웹서비스 개발 및 유지 관리
28. 교육 및 연구용 소프트웨어 관리
29. 학내 정보보안에 관한 대책 수립 및 추진
30. 학내 전산기자재 도입 관리 및 유지 보수 관리
31. 대학 정보전산 자원 이용 지원
32. 정보화교육 운영 및 지원
33. 개인정보보호 업무
34. 기타 전산관리에 관한 사항
35. 소관 제위원회 운영관리에 관한 업무
36. 기타 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제15조(정보도서관) 정보도서관은 다음의 업무를 관장한다.<개정 2016.8.22><개정 2017.2.20.><개정 2021.8.27.>"},{"type":"text","num":"1.","text":"국내․외 기관 및 도서관과의 자료교환 업무"},{"type":"text","num":"2.","text":"도서 구입의뢰, 등록, 분류 및 편목에 관한 업무"},{"type":"text","num":"3.","text":"신착 도서 목록 발간 업무"},{"type":"text","num":"4.","text":"타 기관과 공동 데이터 구축 업무"},{"type":"text","num":"5.","text":"타 대학 도서관 열람의뢰서 및 열람증 발급 업무"},{"type":"text","num":"6.","text":"도서원부 관리 업무"},{"type":"text","num":"7.","text":"도서관 이용교육 및 안내물 제작․홍보 업무"},{"type":"text","num":"8.","text":"자료(공통 선정)선정, 취합 및 발주 업무"},{"type":"text","num":"9.","text":"자유열람실 운영관리에 관한 업무"},{"type":"text","num":"10.","text":"도서관 건물 및 시설물 관리 업무(방역 포함)"},{"type":"text","num":"11.","text":"원문 데이터베이스 구축 업무"},{"type":"text","num":"12.","text":"도서대출 및 반납 업무"},{"type":"text","num":"13.","text":"분실도서 변상 및 연체료 징수에 관한 업무"},{"type":"text","num":"14.","text":"파본도서 수리 및 도서제본에 관한 업무"},{"type":"text","num":"15.","text":"망실, 제적도서에 관한 업무"},{"type":"text","num":"16.","text":"교사자료수집, 보관, 관리업무"},{"type":"text","num":"17.","text":"장서의 보존 관리 및 점검 업무"},{"type":"text","num":"18.","text":"각종 정보자료의 참고문헌 봉사업무"},{"type":"text","num":"19.","text":"각종 간행도서의 보관, 관리 업무"},{"type":"text","num":"20.","text":"자료복사 서비스에 관한 업무"},{"type":"text","num":"21.","text":"학술문헌정보 국내외 기관과 상호대차 업무"},{"type":"text","num":"22.","text":"야간 열람봉사에 관한 업무"},{"type":"text","num":"23.","text":"학내 정보화 계획 및 추진"},{"type":"text","num":"24.","text":"교육 및 연구에 관한 정보처리 지원"},{"type":"text","num":"25.","text":"학사행정, 일반행정, 연구행정에 관한 정보시스템 개발 및 유지 관리"},{"type":"text","num":"26.","text":"전산망 관리 및 운영"},{"type":"text","num":"27.","text":"대학, 부속기관의 웹서비스 개발 및 유지 관리"},{"type":"text","num":"28.","text":"교육 및 연구용 소프트웨어 관리"},{"type":"text","num":"29.","text":"학내 정보보안에 관한 대책 수립 및 추진"},{"type":"text","num":"30.","text":"학내 전산기자재 도입 관리 및 유지 보수 관리"},{"type":"text","num":"31.","text":"대학 정보전산 자원 이용 지원"},{"type":"text","num":"32.","text":"정보화교육 운영 및 지원"},{"type":"text","num":"33.","text":"개인정보보호 업무"},{"type":"text","num":"34.","text":"기타 전산관리에 관한 사항"},{"type":"text","num":"35.","text":"소관 제위원회 운영관리에 관한 업무"},{"type":"text","num":"36.","text":"기타 위 각 호에 부수되는 사항"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 16, '학생생활관', '제7장 부속 및 부설기관', '제16조(학생생활관) 학생생활관은 다음의 업무를 관장한다.<개정 2016.8.22><개정 2017.2.20><개정 2017.09.25>
1. 학생생활관 관장 직인 관리에 관한 업무
2. 생활관 입․퇴사에 관한 업무
3. 사생증 발급에 관한 업무
4. 입사생 각 호실 배정에 관한 업무
5. 입사생 생활관 이용 규칙 제정에 업무
6. 학생생활관 관리․운영에 관한 업무(건물‧가스‧보일러‧청소‧급식‧식당관리 등)
7. 학생생활관 물품 구입 의뢰 및 검수에 관한 업무
8. 학생생활관 예․결산에 관한 업무
9. 기타 학생생활관 관련 업무
10. 소관 제위원회 운영관리에 관한 업무
11. 기타 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제16조(학생생활관) 학생생활관은 다음의 업무를 관장한다.<개정 2016.8.22><개정 2017.2.20><개정 2017.09.25>"},{"type":"text","num":"1.","text":"학생생활관 관장 직인 관리에 관한 업무"},{"type":"text","num":"2.","text":"생활관 입․퇴사에 관한 업무"},{"type":"text","num":"3.","text":"사생증 발급에 관한 업무"},{"type":"text","num":"4.","text":"입사생 각 호실 배정에 관한 업무"},{"type":"text","num":"5.","text":"입사생 생활관 이용 규칙 제정에 업무"},{"type":"text","num":"6.","text":"학생생활관 관리․운영에 관한 업무(건물‧가스‧보일러‧청소‧급식‧식당관리 등)"},{"type":"text","num":"7.","text":"학생생활관 물품 구입 의뢰 및 검수에 관한 업무"},{"type":"text","num":"8.","text":"학생생활관 예․결산에 관한 업무"},{"type":"text","num":"9.","text":"기타 학생생활관 관련 업무"},{"type":"text","num":"10.","text":"소관 제위원회 운영관리에 관한 업무"},{"type":"text","num":"11.","text":"기타 위 각 호에 부수되는 사항"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 17, '국제교류협력단', '제7장 부속 및 부설기관', '제17조(국제교류협력단) 국제교류협력단은 다음의 업무를 관장한다.<개정 2016.8.22><개정 2017.2.20.><개정 2017.09.25.><개정 2025.09.24>
1. 국제교류에 관한 계획 수립
2. 국제교류 프로그램 개발·운영
3. 외국의 대학, 기관과의 협정체결 및 교류사업 추진
4. 학생교환 및 장·단기 파견에 관한 사항
5. 학생 및 교수관련 국제교류업무 지원
6. 유학생 입학 및 체류관련 지원
7. 외국인 교수의 체류관련 지원
8. 해외인사 방문에 관한 사항
9. 대학안내자료(외국어) 제작 및 국제 홍보
10. 국제정보자료실 운영에 관한 사항
11. 국제교육에 관한 계획 수립
12. 재학생 및 외부인의 국제화 교육
13. 재외국민 및 외국인의 한국어문화 교육
14. 언어 및 국제교육에 관련된 교육과정 및 시설의 운영
15. 외국어 및 한국어 능력 측정
16. 본교 및 외부기관의 국제화 위탁교육
17. 국제교류교육원의 사업수행에 필요한 연구
18. 국제사회지도자과정 등 공개강좌 운영
19. 교정, 번역 업무
20. 유학생 오리엔테이션에 관한 업무
21. 유학생 기숙사(학생생활관) 배정에 관한 지원 업무
22. 유학생 정기적인 상담 및 학교생활 적응을 위한 도우미 지정 및 운영에 관한 업무
23. 유학생 장학금 지급(입학금‧기숙사비‧수업료 등) 관련 지원 업무
24. 유학생 관리방안 마련 및 이탈자 발생시 관련부서 통보에 관한 업무
25. 유학생 수강신청지도 등에 관한 지원 업무
26. 유학생 모집(국내외 유학원 관리‧홍보 등)에 관한 업무
27. 유학생 입학(사증발급)에 관한 업무
28. 외국인 입국 및 외국인 등록에 관한 업무
29. 이탈‧미등록 등 고유목적 변경에 관한 관할 출입국관리사무소 보고 업무
30. 선발 유학생 관련 제반 사항 관련부서 통보
31. 교원 해외 파견 대상자 선정 및 관리에 관한 업무
32. 학생 및 교수의 국제교류에 관한 업무
33. 국제 학술문화교류에 관한 업무
34. 기타 위 각 호에 부수되는 사항
35. 외국인 등록금 납부 현황 관리에 관한 업무 ,전산시스템 등록관리<개정 2025.09.24.>

', '[{"type":"text","num":"","text":"제17조(국제교류협력단) 국제교류협력단은 다음의 업무를 관장한다.<개정 2016.8.22><개정 2017.2.20.><개정 2017.09.25.><개정 2025.09.24>"},{"type":"text","num":"1.","text":"국제교류에 관한 계획 수립"},{"type":"text","num":"2.","text":"국제교류 프로그램 개발·운영"},{"type":"text","num":"3.","text":"외국의 대학, 기관과의 협정체결 및 교류사업 추진"},{"type":"text","num":"4.","text":"학생교환 및 장·단기 파견에 관한 사항"},{"type":"text","num":"5.","text":"학생 및 교수관련 국제교류업무 지원"},{"type":"text","num":"6.","text":"유학생 입학 및 체류관련 지원"},{"type":"text","num":"7.","text":"외국인 교수의 체류관련 지원"},{"type":"text","num":"8.","text":"해외인사 방문에 관한 사항"},{"type":"text","num":"9.","text":"대학안내자료(외국어) 제작 및 국제 홍보"},{"type":"text","num":"10.","text":"국제정보자료실 운영에 관한 사항"},{"type":"text","num":"11.","text":"국제교육에 관한 계획 수립"},{"type":"text","num":"12.","text":"재학생 및 외부인의 국제화 교육"},{"type":"text","num":"13.","text":"재외국민 및 외국인의 한국어문화 교육"},{"type":"text","num":"14.","text":"언어 및 국제교육에 관련된 교육과정 및 시설의 운영"},{"type":"text","num":"15.","text":"외국어 및 한국어 능력 측정"},{"type":"text","num":"16.","text":"본교 및 외부기관의 국제화 위탁교육"},{"type":"text","num":"17.","text":"국제교류교육원의 사업수행에 필요한 연구"},{"type":"text","num":"18.","text":"국제사회지도자과정 등 공개강좌 운영"},{"type":"text","num":"19.","text":"교정, 번역 업무"},{"type":"text","num":"20.","text":"유학생 오리엔테이션에 관한 업무"},{"type":"text","num":"21.","text":"유학생 기숙사(학생생활관) 배정에 관한 지원 업무"},{"type":"text","num":"22.","text":"유학생 정기적인 상담 및 학교생활 적응을 위한 도우미 지정 및 운영에 관한 업무"},{"type":"text","num":"23.","text":"유학생 장학금 지급(입학금‧기숙사비‧수업료 등) 관련 지원 업무"},{"type":"text","num":"24.","text":"유학생 관리방안 마련 및 이탈자 발생시 관련부서 통보에 관한 업무"},{"type":"text","num":"25.","text":"유학생 수강신청지도 등에 관한 지원 업무"},{"type":"text","num":"26.","text":"유학생 모집(국내외 유학원 관리‧홍보 등)에 관한 업무"},{"type":"text","num":"27.","text":"유학생 입학(사증발급)에 관한 업무"},{"type":"text","num":"28.","text":"외국인 입국 및 외국인 등록에 관한 업무"},{"type":"text","num":"29.","text":"이탈‧미등록 등 고유목적 변경에 관한 관할 출입국관리사무소 보고 업무"},{"type":"text","num":"30.","text":"선발 유학생 관련 제반 사항 관련부서 통보"},{"type":"text","num":"31.","text":"교원 해외 파견 대상자 선정 및 관리에 관한 업무"},{"type":"text","num":"32.","text":"학생 및 교수의 국제교류에 관한 업무"},{"type":"text","num":"33.","text":"국제 학술문화교류에 관한 업무"},{"type":"text","num":"34.","text":"기타 위 각 호에 부수되는 사항"},{"type":"text","num":"35.","text":"외국인 등록금 납부 현황 관리에 관한 업무 ,전산시스템 등록관리<개정 2025.09.24.>"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 18, '평생교육원', '제7장 부속 및 부설기관', '제18조(평생교육원) 평생교육원은 다음의 업무를 관장한다.
1. 지역사회 주민을 위한 장․단기 평생교육계획 수립
2. 평생교육에 관한 제반 연구
3. 평생교육 자료의 개발과 보존
4. 수강생 정원 관리에 관한 업무
5. 수강생 선발에 관한 업무
6. 학사계획 수립 및 조정 업무(강좌의 설치 및 폐지 등)
7. 등록 및 수강신청, 교육과정 편성에 관한 업무
8. 시험 및 성적, 출결관리 업무
9. 소속 교원 위촉 및 출강관리에 관한 업무
10. 휴강, 결강, 보강에 관한 업무
11. 학적부 작성 및 관리업무
12. 수료에 관한 업무
13. 각종 증명서 발급에 관한 업무
14. 예․결산에 관한 업무
15. 평생교육원 운영 관리에 필요한 각종 인․허가 업무
16. 홍보 및 행사에 관한 업무
17. 상담 및 지도에 관한 업무
18. 장학생 관리 및 장학금 운영․관리에 관한 업무
19. 외부(중등교사 컴퓨터 자격, 초등어학) 위탁 교육에 관한 업무
20. 자체 교원 인력수습에 관한 업무
21. 수강료 및 강사료 결정 업무
22. 평생교육원장 직인 관리에 관한 업무
23. 기타 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제18조(평생교육원) 평생교육원은 다음의 업무를 관장한다."},{"type":"text","num":"1.","text":"지역사회 주민을 위한 장․단기 평생교육계획 수립"},{"type":"text","num":"2.","text":"평생교육에 관한 제반 연구"},{"type":"text","num":"3.","text":"평생교육 자료의 개발과 보존"},{"type":"text","num":"4.","text":"수강생 정원 관리에 관한 업무"},{"type":"text","num":"5.","text":"수강생 선발에 관한 업무"},{"type":"text","num":"6.","text":"학사계획 수립 및 조정 업무(강좌의 설치 및 폐지 등)"},{"type":"text","num":"7.","text":"등록 및 수강신청, 교육과정 편성에 관한 업무"},{"type":"text","num":"8.","text":"시험 및 성적, 출결관리 업무"},{"type":"text","num":"9.","text":"소속 교원 위촉 및 출강관리에 관한 업무"},{"type":"text","num":"10.","text":"휴강, 결강, 보강에 관한 업무"},{"type":"text","num":"11.","text":"학적부 작성 및 관리업무"},{"type":"text","num":"12.","text":"수료에 관한 업무"},{"type":"text","num":"13.","text":"각종 증명서 발급에 관한 업무"},{"type":"text","num":"14.","text":"예․결산에 관한 업무"},{"type":"text","num":"15.","text":"평생교육원 운영 관리에 필요한 각종 인․허가 업무"},{"type":"text","num":"16.","text":"홍보 및 행사에 관한 업무"},{"type":"text","num":"17.","text":"상담 및 지도에 관한 업무"},{"type":"text","num":"18.","text":"장학생 관리 및 장학금 운영․관리에 관한 업무"},{"type":"text","num":"19.","text":"외부(중등교사 컴퓨터 자격, 초등어학) 위탁 교육에 관한 업무"},{"type":"text","num":"20.","text":"자체 교원 인력수습에 관한 업무"},{"type":"text","num":"21.","text":"수강료 및 강사료 결정 업무"},{"type":"text","num":"22.","text":"평생교육원장 직인 관리에 관한 업무"},{"type":"text","num":"23.","text":"기타 위 각 호에 부수되는 사항"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 19, '게임교육센터', '제7장 부속 및 부설기관', '제19조(게임교육센터) 평생교육원에 게임교육센터를 두고 다음 사항을 관장한다.
1. 장․단기 게임교육센터 교육계획 수립
2. 게임교육에 관한 제반 연구
3. 수강생 정원 관리에 관한 업무
4. 수강생 선발에 관한 업무
5. 학사계획 수립 및 조정 업무(강좌의 설치 및 폐지 등)
6. 등록 및 수강신청, 교육과정 편성에 관한 업무
7. 시험 및 성적, 출결관리 업무
8. 소속 교원 위촉 및 출강관리에 관한 업무
9. 휴강, 결강, 보강에 관한 업무
10. 학적부 작성 및 관리업무
11. 수료에 관한 업무
12. 각종 증명서 발급에 관한 업무
13. 예․결산에 관한 업무
14. 게임교육센터 운영 관리에 필요한 각종 인․허가 업무
15. 홍보 및 행사에 관한 업무
16. 상담 및 지도에 관한 업무
17. 장학생 관리 및 장학금 운영․관리에 관한 업무
18. 외부 위탁 교육에 관한 업무
19. 자체 교원 인력수습에 관한 업무
20. 수강료 및 강사료 결정 업무
21. 기타 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제19조(게임교육센터) 평생교육원에 게임교육센터를 두고 다음 사항을 관장한다."},{"type":"text","num":"1.","text":"장․단기 게임교육센터 교육계획 수립"},{"type":"text","num":"2.","text":"게임교육에 관한 제반 연구"},{"type":"text","num":"3.","text":"수강생 정원 관리에 관한 업무"},{"type":"text","num":"4.","text":"수강생 선발에 관한 업무"},{"type":"text","num":"5.","text":"학사계획 수립 및 조정 업무(강좌의 설치 및 폐지 등)"},{"type":"text","num":"6.","text":"등록 및 수강신청, 교육과정 편성에 관한 업무"},{"type":"text","num":"7.","text":"시험 및 성적, 출결관리 업무"},{"type":"text","num":"8.","text":"소속 교원 위촉 및 출강관리에 관한 업무"},{"type":"text","num":"9.","text":"휴강, 결강, 보강에 관한 업무"},{"type":"text","num":"10.","text":"학적부 작성 및 관리업무"},{"type":"text","num":"11.","text":"수료에 관한 업무"},{"type":"text","num":"12.","text":"각종 증명서 발급에 관한 업무"},{"type":"text","num":"13.","text":"예․결산에 관한 업무"},{"type":"text","num":"14.","text":"게임교육센터 운영 관리에 필요한 각종 인․허가 업무"},{"type":"text","num":"15.","text":"홍보 및 행사에 관한 업무"},{"type":"text","num":"16.","text":"상담 및 지도에 관한 업무"},{"type":"text","num":"17.","text":"장학생 관리 및 장학금 운영․관리에 관한 업무"},{"type":"text","num":"18.","text":"외부 위탁 교육에 관한 업무"},{"type":"text","num":"19.","text":"자체 교원 인력수습에 관한 업무"},{"type":"text","num":"20.","text":"수강료 및 강사료 결정 업무"},{"type":"text","num":"21.","text":"기타 위 각 호에 부수되는 사항"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 20, '원격평생교육원', '제7장 부속 및 부설기관', '제20조(원격평생교육원) 원격평생교육원은 다음의 업무를 관장한다.<조신설 2015.1.13>
