INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 22, '기타 부속 ․ 부설기관', '제7장 부속 및 부설기관', '제22조(기타 부속 ․ 부설기관) 이 규정에 사무분장 사항이 규정되지 아니한 부속 ․ 부설기관의 사무분장 은 당해 기관의 규정에 의한다. 제8장 입학홍보처

