INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 23, '제23조의1(입학지원팀,학생지원팀)', '제7장 부속 및 부설기관', '제23조의1(입학지원팀,학생지원팀) 입학홍보처에 입학지원팀과 학생지원팀을 두고 다음 사항을 분장한
다. <조신설 2021.07.22.><개정 2023.11.07>
① 학생업무
1. 학생지도계획 수립
2. 학생자치기구의 활동지도
3. 학생 동아리 활동지도
4. 학생카드 관리에 관한 업무
5. 신입생 오리엔테이션에 관한 업무
6. 학생 상벌에 관한 업무
7. 학생증 제작 및 교부에 관한 업무
8. 졸업앨범 및 졸업기념품제작 활동지도
9. 학생 병사에 관한 업무
10. 직장예비군 편성 및 운영, 관리에 관한 업무
11. 교직원 민방위에 관한 업무
12. 근로학생 관리에 관한 업무
13. 동아리 구성ㆍ활동 및 지도에 관한 업무
14. 학생 봉사활동 지도 및 지원에 관한 업무
15. 학생 해외유학ㆍ연수 및 일반연수에 관한 업무
16. 장학생 선발 및 장학금 급여에 관한 업무
17. 학자금 융자 및 관리에 관한 업무
18. 대여 장학금 관리에 관한 업무
19. 부업 알선에 관한 업무
20. 교환 장학생 선발에 관한 업무
21. 동창회 업무 협조
22. 스쿨버스 운행 계획 수립 및 운영에 관한 업무
23. 기타 장학 및 학생복지에 관한 사항
24. 보건업무
25. 성폭력상담실 운영
26. 정신건강 및 학생 생활 상담
27. 학생병무업무
28. 소관 제위원회 운영관리에 관한 업무
29. 그 밖에 위 각 호에 부수되는 사항
② 입학 업무
1. 입학전형 기본계획 수립
2. 입학홍보 계획수립 및 점검에 관한 업무
3. 입학홍보 평가 및 분석에 관한 업무
4. 입학홍보 책자 발간 및 배포에 관한 업무
5. 입학홍보 도우미 선발 및 기념품 제작
6. 홍보용 사진 및 VTR 촬영ㆍ관리 업무
7. 신ㆍ편입생 모집요강 주요사항 결정, 모집요강 제작 및 교부
8. 입학사정에 관한 업무
9. 입학관련위원회 업무
10. 입학전형 실시계획서 수립
11. 입학전형에 따른 제반 업무
12. 입학허가, 등록 및 등록취소, 입학취소
13. 교육편제의 개편 및 학생정원 조정과 관리
14. 입학결과 보고
15. 입학(신입학, 편입학, 재입학, 재외국민)에 관한 업무
16. 입학 전·후 추수 지도

', '[{"type":"text","num":"","text":"제23조의1(입학지원팀,학생지원팀) 입학홍보처에 입학지원팀과 학생지원팀을 두고 다음 사항을 분장한"},{"type":"text","num":"다.","text":"<조신설 2021.07.22.><개정 2023.11.07>"},{"type":"text","num":"①","text":"학생업무"},{"type":"text","num":"1.","text":"학생지도계획 수립"},{"type":"text","num":"2.","text":"학생자치기구의 활동지도"},{"type":"text","num":"3.","text":"학생 동아리 활동지도"},{"type":"text","num":"4.","text":"학생카드 관리에 관한 업무"},{"type":"text","num":"5.","text":"신입생 오리엔테이션에 관한 업무"},{"type":"text","num":"6.","text":"학생 상벌에 관한 업무"},{"type":"text","num":"7.","text":"학생증 제작 및 교부에 관한 업무"},{"type":"text","num":"8.","text":"졸업앨범 및 졸업기념품제작 활동지도"},{"type":"text","num":"9.","text":"학생 병사에 관한 업무"},{"type":"text","num":"10.","text":"직장예비군 편성 및 운영, 관리에 관한 업무"},{"type":"text","num":"11.","text":"교직원 민방위에 관한 업무"},{"type":"text","num":"12.","text":"근로학생 관리에 관한 업무"},{"type":"text","num":"13.","text":"동아리 구성ㆍ활동 및 지도에 관한 업무"},{"type":"text","num":"14.","text":"학생 봉사활동 지도 및 지원에 관한 업무"},{"type":"text","num":"15.","text":"학생 해외유학ㆍ연수 및 일반연수에 관한 업무"},{"type":"text","num":"16.","text":"장학생 선발 및 장학금 급여에 관한 업무"},{"type":"text","num":"17.","text":"학자금 융자 및 관리에 관한 업무"},{"type":"text","num":"18.","text":"대여 장학금 관리에 관한 업무"},{"type":"text","num":"19.","text":"부업 알선에 관한 업무"},{"type":"text","num":"20.","text":"교환 장학생 선발에 관한 업무"},{"type":"text","num":"21.","text":"동창회 업무 협조"},{"type":"text","num":"22.","text":"스쿨버스 운행 계획 수립 및 운영에 관한 업무"},{"type":"text","num":"23.","text":"기타 장학 및 학생복지에 관한 사항"},{"type":"text","num":"24.","text":"보건업무"},{"type":"text","num":"25.","text":"성폭력상담실 운영"},{"type":"text","num":"26.","text":"정신건강 및 학생 생활 상담"},{"type":"text","num":"27.","text":"학생병무업무"},{"type":"text","num":"28.","text":"소관 제위원회 운영관리에 관한 업무"},{"type":"text","num":"29.","text":"그 밖에 위 각 호에 부수되는 사항"},{"type":"text","num":"②","text":"입학 업무"},{"type":"text","num":"1.","text":"입학전형 기본계획 수립"},{"type":"text","num":"2.","text":"입학홍보 계획수립 및 점검에 관한 업무"},{"type":"text","num":"3.","text":"입학홍보 평가 및 분석에 관한 업무"},{"type":"text","num":"4.","text":"입학홍보 책자 발간 및 배포에 관한 업무"},{"type":"text","num":"5.","text":"입학홍보 도우미 선발 및 기념품 제작"},{"type":"text","num":"6.","text":"홍보용 사진 및 VTR 촬영ㆍ관리 업무"},{"type":"text","num":"7.","text":"신ㆍ편입생 모집요강 주요사항 결정, 모집요강 제작 및 교부"},{"type":"text","num":"8.","text":"입학사정에 관한 업무"},{"type":"text","num":"9.","text":"입학관련위원회 업무"},{"type":"text","num":"10.","text":"입학전형 실시계획서 수립"},{"type":"text","num":"11.","text":"입학전형에 따른 제반 업무"},{"type":"text","num":"12.","text":"입학허가, 등록 및 등록취소, 입학취소"},{"type":"text","num":"13.","text":"교육편제의 개편 및 학생정원 조정과 관리"},{"type":"text","num":"14.","text":"입학결과 보고"},{"type":"text","num":"15.","text":"입학(신입학, 편입학, 재입학, 재외국민)에 관한 업무"},{"type":"text","num":"16.","text":"입학 전·후 추수 지도"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 23, '제23조의2(학생상담센터)', '제7장 부속 및 부설기관', '제23조의2(학생상담센터) 입학홍보처에 학생상담센터를 두고 다음 각 호의 업무를 담당한다.
1. 개인 ․ 집단상담 계획 수립 및 활동
2. 각종 심리검사 및 전문상담
3. 대학생활 증진프로그램 운영
4. 자원봉사자 운영 및 교육
5. 학생생활과 관련된 조사 연구 및 상담교육 프로그램의 개발 ․ 연구
6. 장애학생 관련 상담 업무
7. 성희롱 및 성폭력 예방과 처리
8. 그 밖에 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제23조의2(학생상담센터) 입학홍보처에 학생상담센터를 두고 다음 각 호의 업무를 담당한다."},{"type":"text","num":"1.","text":"개인 ․ 집단상담 계획 수립 및 활동"},{"type":"text","num":"2.","text":"각종 심리검사 및 전문상담"},{"type":"text","num":"3.","text":"대학생활 증진프로그램 운영"},{"type":"text","num":"4.","text":"자원봉사자 운영 및 교육"},{"type":"text","num":"5.","text":"학생생활과 관련된 조사 연구 및 상담교육 프로그램의 개발 ․ 연구"},{"type":"text","num":"6.","text":"장애학생 관련 상담 업무"},{"type":"text","num":"7.","text":"성희롱 및 성폭력 예방과 처리"},{"type":"text","num":"8.","text":"그 밖에 위 각 호에 부수되는 사항"}]');
INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 23, '제23조의3(장애학생지원센터)', '제7장 부속 및 부설기관', '제23조의3(장애학생지원센터) 입학홍보처에 장애학생지원센터를 두고 다음 각 호의 업무를 담당한다.
1. 장애학생 관리
2. 장애학생 지원 계획 수립
3. 장애학생 교수 ․ 학습 지원 및 조정 프로그램 개발 ․ 보급 계획
4. 장애학생 편의시설의 제공 및 개선
5. 장애인식 개선을 위한 문화 및 교육사업
6. 장애도우미지원사업 기획 및 운영
7. 장애학생 증진프로그램 운영
8. 장애학생생활과 관련된 조사 연구 및 프로그램의 개발 ․ 연구
9. 장애학생운영위원회 및 장애학생특별지원위원회 운영
10. 그 밖에 위 각 호에 부수되는 사항

', '[{"type":"text","num":"","text":"제23조의3(장애학생지원센터) 입학홍보처에 장애학생지원센터를 두고 다음 각 호의 업무를 담당한다."},{"type":"text","num":"1.","text":"장애학생 관리"},{"type":"text","num":"2.","text":"장애학생 지원 계획 수립"},{"type":"text","num":"3.","text":"장애학생 교수 ․ 학습 지원 및 조정 프로그램 개발 ․ 보급 계획"},{"type":"text","num":"4.","text":"장애학생 편의시설의 제공 및 개선"},{"type":"text","num":"5.","text":"장애인식 개선을 위한 문화 및 교육사업"},{"type":"text","num":"6.","text":"장애도우미지원사업 기획 및 운영"},{"type":"text","num":"7.","text":"장애학생 증진프로그램 운영"},{"type":"text","num":"8.","text":"장애학생생활과 관련된 조사 연구 및 프로그램의 개발 ․ 연구"},{"type":"text","num":"9.","text":"장애학생운영위원회 및 장애학생특별지원위원회 운영"},{"type":"text","num":"10.","text":"그 밖에 위 각 호에 부수되는 사항"}]');
