INSERT INTO Article (id, revisionId, articleNumber, title, chapter, contentText, contentJson) VALUES (lower(hex(randomblob(16))), 'de348873-195e-4828-8fde-5d689bc8577a', 23, '제23조의5(취업·창업지원센터)', '제7장 부속 및 부설기관', '제23조의5(취업·창업지원센터) 입학홍보처에 취업·창업지원센터를 두고 다음 각 호의 업무를 담당한
다. 
